  config: ConfigYaml,
  cliListen: string,
  configPath: string,
  pkgVersion: string,
  pkgName: string,
  callback: Callback
): void {
  if (_.isObject(config) === false) {
    throw new Error(API_ERROR.CONFIG_BAD_FORMAT);
  }

  initLogger(config);

  // merge flags and experiments for backward compatibility
  const flags = {
    ...(config?.flags || {}),
    ...(config?.experiments || {}),
  };
  displayExperimentsInfoBox(flags);
  logger.warn('This is a deprecated method, please use runServer instead');

  endPointAPI(config).then((app): void => {
    const listen = cliListen ?? config?.listen;
    const addr = getListenAddress(listen, logger);
    let webServer;
    if (addr.proto === 'https') {
      webServer = handleHTTPS(app, configPath, config);
    } else {
